UPDATE 
    KEPTITEM /* 세금계산서 품목정보 */
SET 
    REMARK_DESCRIPTION      = #{REMARK_DESCRIPTION}
  , REMARK_SPECIFICATION    = #{REMARK_SPECIFICATION}
  , REMARK_QTY              = #{REMARK_QTY}
  , REMARK_PRICE            = #{REMARK_PRICE}
  , SUPP_PRICE              = #{SUPP_PRICE}
  , TAX_PRICE               = #{TAX_PRICE}
  , REMARK_DATE             = TO_CHAR(SYSDATE, 'YYYYMMDD')
  , REMARK   					= #{REMARK}
WHERE
    TAX_BILL_NO             = #{st_tax_bill_no}
AND ITEM_SEQ                = LPAD(#{ITEM_SEQ}, 6, 0)

/*insertMasterCmClStndSettingPop*/

		INSERT INTO BILL_ACCOUNTING
		(
		    ACCOUNTING_CODE
		  , SITE
		  , COM_CODE
		  , IRS_NO
		  , USER_NAME_LOC
		  , PHONE_NUMBER
		  , FAX_NUMBER
		  , EMAIL
		  , CREATE_USER_ID
		  , CREATE_DATE
		  , PRIORITY
		)
		VALUES
		(
		    (SELECT MAX(ACCOUNTING_CODE)+1 FROM BILL_ACCOUNTING)
		  , #{st_sys_type}
		  , #{st_buyer_code}
		  , #{st_buyer_irs_no}
		  , #{USER_NAME_LOC} 
		  , #{PHONE_NUMBER} 
		  , #{FAX_NUMBER} 
		  , #{EMAIL}  
		  , #{st_user_id}
		  , SYSDATE
		  , DECODE(#{PRIORITY},'0','N','Y') 
		)

/*updateMasterCmClStndSettingPop*/

		UPDATE BILL_ACCOUNTING
		SET USER_NAME_LOC =#{USER_NAME_LOC}
		  , PHONE_NUMBER = #{PHONE_NUMBER}
		  , FAX_NUMBER = #{FAX_NUMBER}
		  , EMAIL = #{EMAIL}
		  , PRIORITY = DECODE(#{PRIORITY},'0','N','Y')
		WHERE ACCOUNTING_CODE  = #{ACCOUNTING_CODE}

