/*selectMasterCmClIssueIdInfoPop*/ SELECT DISTINCT A.ISSUE_DATE ,DECODE(A.ARAP,'AR','매출','AP','매입') ARAP ,A.ISSUE_ID , DECODE(A.TYPE_CODE,'0101','일반 세금계산서' ,'0102','영세율 세금계산서' ,'0201','수정 일반 세금계산서' ,'0202','수정 영세율 세금계산서' ,'0301','일반 계산서') TYPE_CODE , A.CHARGETOTAL , A.TAXTOTAL , A.GRANDTOTAL , A.ASP_CODE , A.SU_EMAIL , A.SU_PERSNAME , A.IP_EMAIL1 , A.IP_PERSNAME1 , DECODE(A.ARAP,'AP',A.SU_NAME,'AR',IP_NAME) IP_NAME , DECODE(A.ARAP,'AP',A.SU_ID,'AR',IP_ID) IP_ID , A.DESC_TEXT1 , A.AMEND_CODE FROM KEPTAX.ZDTV3T_NTS A, TACCOUNT_TAX_MAPPING B WHERE A.ISSUE_ID = B.ISSUE_ID(+) AND A.ISSUE_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.ARAP= #{st_ar_ap} AND A.GROUP_KEY IS NULL
AND A.IP_ID= #{st_irs_no}
AND A.SU_ID = #{st_irs_no}
AND B.GROUP_KEY = #{st_group_key}
AND B.MAPPING_STATUS IS NOT NULL
AND B.MAPPING_STATUS IS NULL
AND A.IP_EMAIL1 LIKE #{st_ip_email}||'%'
AND A.SU_EMAIL LIKE #{st_su_email}||'%'

/* selectMasterCmClIssueIdInfoPopY */ SELECT DISTINCT A.A01_REGNO AS IRS_NO , A.A01_CUSTOMERNM AS IRS_NAME , DECODE(A.ACODE, '1114805', '매입', '2112605', '매출') AS ACODE , A.ACCNO , A.ACCSEQ , A.PRIN_AMOUNT , DECODE(A.ACODE, '2112605', A.CREDIT, '1114805', A.DEBIT) AS TAX , A.REFNO2 AS KEP_TAX_BILL_NO FROM TACCOUNT_TAX_IF A, TACCOUNT_TAX_MAPPING B WHERE 1=1 AND A.ACCNO = B.ACCNO AND A.ACCSEQ = B.ACCSEQ AND A.STATUS IN ('C', 'R') AND B.STATUS IN ('C', 'R')
AND B.GROUP_KEY IN
#{item}

/* selectMasterCmClIssueIdInfoPopN */ SELECT DISTINCT A01_REGNO AS IRS_NO , A01_CUSTOMERNM AS IRS_NAME , DECODE(ACODE, '1114805', '매입', '2112605', '매출') AS ACODE , ACCNO , ACCSEQ , PRIN_AMOUNT , DECODE(ACODE, '2112605', CREDIT, '1114805', DEBIT) AS TAX , REFNO2 AS KEP_TAX_BILL_NO FROM TACCOUNT_TAX_IF WHERE 1=1 AND STATUS IN ('C', 'R')
AND ACCNO||ACCSEQ IN
#{item}
